    # using the key column and the marker's row as the corner.
    markers = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color and not (r == 0 and start <= c <= end):
                markers.setdefault(color, []).append((r, c))
    for key_c, color, side in ((left_c, left_color, "left"), (right_c, right_color, "right")):
        matches = markers.get(color, [])
